+++ b/src/crispembed.cpp
@@ -1838,6 +1838,13 @@ static std::vector<float> encode_tokens(crispembed_context * ctx, const embed_to
         }
     }

+    // Test-only actual pooling buffer capture, enabled only by this hosted overlay.
+    if (const char * path = std::getenv("CRISPEMBED_TRACE_POOL")) {
+        const std::string file = std::string(path) + ".mean.f32";
+        FILE * f = fopen(file.c_str(), "wb");
+        if (!f || fwrite(pooled.data(), sizeof(float), pooled.size(), f) != pooled.size()) std::abort();
