     // L2 normalize
     auto t_pool = std::chrono::steady_clock::now();
     float norm = 0;
@@ -1857,6 +1864,14 @@ static std::vector<float> encode_tokens(crispembed_context * ctx, const embed_to
         fprintf(stderr, "[crispembed-bench] encode_tokens total: %.1f ms\n", ms_total);
     }

+    // Test-only actual pooling buffer capture, enabled only by this hosted overlay.
+    if (const char * path = std::getenv("CRISPEMBED_TRACE_POOL")) {
+        const std::string file = std::string(path) + ".final.f32";
+        FILE * f = fopen(file.c_str(), "wb");
+        if (!f || fwrite(pooled.data(), sizeof(float), pooled.size(), f) != pooled.size()) std::abort();
